// frontend/src/components/CreateEventForm.tsx
import React, { useState } from "react";
import api from "../services/api";

type Attendee = { name: string; email: string };

export default function CreateEventForm({ onCreated }: { onCreated: () => void }) {
  const [name, setName] = useState("");
  const [venue, setVenue] = useState("");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [attendees, setAttendees] = useState<Attendee[]>([]);

  function addAttendee() {
    setAttendees(prev => [...prev, { name: "", email: "" }]);
  }

  function updateAttendee(i:number, field: string, value:string) {
    setAttendees(prev => prev.map((a, idx) => idx === i ? { ...a, [field]: value } : a));
  }

  const submit = async (e:React.FormEvent) => {
    e.preventDefault();
    const payload = {
      name,
      venue,
      startTime: new Date(start).toISOString(),
      endTime: new Date(end).toISOString(),
      attendees
    };
    await api.post("/api/events", {
      name,
      startTime: new Date(start),
      endTime: new Date(end),
      venue,
      attendees
    });
    onCreated();
  };

  return (
    <form onSubmit={submit}>
      <input value={name} onChange={e => setName(e.target.value)} placeholder="Event name" />
      <input type="datetime-local" value={start} onChange={e => setStart(e.target.value)} />
      <input type="datetime-local" value={end} onChange={e => setEnd(e.target.value)} />
      <input value={venue} onChange={e => setVenue(e.target.value)} placeholder="Venue" />
      <button type="button" onClick={addAttendee}>Add attendee</button>
      {attendees.map((a, i) => (
        <div key={i}>
          <input placeholder="Name" value={a.name} onChange={e => updateAttendee(i,"name",e.target.value)} />
          <input placeholder="Email" value={a.email} onChange={e => updateAttendee(i,"email",e.target.value)} />
        </div>
      ))}
      <button type="submit">Create Event</button>
    </form>
  );
}
